extern bitstr_t * core_array_to_bitmap ( bitstr_t * * core_array ) { bitstr_t * core_bitmap = NULL ; int i ; int c , core_offset ; char tmp [ 128 ] ; if ( ! core_array ) { return core_bitmap ; } for ( i = 0 ; i < core_array_size ; i ++ ) { bit_fmt ( tmp , sizeof ( tmp ) , core_array [ i ] ) ; error ( "OUT core bitmap[%d] %s" , i , tmp ) ; } if ( ! is_cons_tres ) { core_bitmap = * core_array ; * core_array = NULL ; return core_bitmap ; } core_bitmap = bit_alloc ( cr_get_coremap_offset ( node_record_count ) ) ; for ( i = 0 ; i < core_array_size ; i ++ ) { if ( ! core_array [ i ] ) { continue ; } core_offset = cr_get_coremap_offset ( i ) ; for ( c = 0 ; c < node_record_table_ptr [ i ] -> tot_cores ; c ++ ) { if ( bit_test ( core_array [ i ] , c ) ) { bit_set ( core_bitmap , core_offset + c ) ; } } } bit_fmt ( tmp , sizeof ( tmp ) , core_bitmap ) ; error ( "IN core bitmap %s" , tmp ) ; return core_bitmap ; } 